pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, uint256 warpTime) public {
        vm.assume(sender != address(0));
        warpTime = bound(warpTime, block.timestamp + 1, type(uint256).max/2);

        vm.deal(sender, 20 ether);

        vm.warp(warpTime);

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok == true);

        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}
